import{_ as e}from"./chunks/main_page.iLigAlA3.js";import{_ as a,o as r,c as o,a0 as i}from"./chunks/framework.akKRIpjQ.js";const m=JSON.parse('{"title":"📚 AceCrush-Craft Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function d(s,t,l,h,c,u){return r(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="📚-acecrush-craft-documentation" tabindex="-1">📚 AceCrush-Craft Documentation <a class="header-anchor" href="#📚-acecrush-craft-documentation" aria-label="Permalink to &quot;📚 AceCrush-Craft Documentation&quot;">​</a></h1><p><strong>English</strong> | <a href="./zh/">简体中文</a></p><h2 id="what-is-this" tabindex="-1">What is this? <a class="header-anchor" href="#what-is-this" aria-label="Permalink to &quot;What is this?&quot;">​</a></h2><p><code>AceCrush Craft</code> is a <strong>tennis-equipment data tool</strong> for racket sport enthusiasts — not another &quot;tennis community app&quot;, but a small, offline-first utility that bundles the <strong>four</strong> everyday calculations and records players actually use:</p><table tabindex="0"><thead><tr><th>#</th><th>Feature</th><th>What you get</th></tr></thead><tbody><tr><td>1</td><td><strong>AI grip size</strong></td><td>Palm photo → recommended grip size in Yonex / Wilson / Head-Prince-Babolat systems</td></tr><tr><td>2</td><td><strong>Racket profile</strong></td><td>Record specs &amp; notes for every racket you own</td></tr><tr><td>3</td><td><strong>Stringing log</strong></td><td>One record per restring, with automatic reminders</td></tr><tr><td>4</td><td><strong>Tension conversion</strong></td><td>DT ⇄ RT ⇄ lbs ⇄ kg cross-calculator; tap &quot;Use this tension&quot; to send the result straight into the stringing log</td></tr></tbody></table><p>All data lives in the device&#39;s local SQLite — <strong>no upload, no network</strong>. AI grip measurement activates only when <strong>you</strong> press the camera shutter, and runs on-device by default.</p><hr><p><a id="download"></a></p><h2 id="📥-download" tabindex="-1">📥 Download <a class="header-anchor" href="#📥-download" aria-label="Permalink to &quot;📥 Download&quot;">​</a></h2><blockquote><p><strong>Currently supported platforms</strong>: <strong>Android</strong> (iOS version is not yet released).</p><p><strong>Latest release</strong>: V1.0.x</p></blockquote><p><strong>Download link: <a href="https://github.com/acecrush-dev/acecrush-craft-app/releases" target="_blank" rel="noreferrer">https://github.com/acecrush-dev/acecrush-craft-app/releases</a></strong></p><p>Each release ships <code>app-release.apk</code> + a SHA-256 checksum.</p><img src="'+e+'" alt="AceCrush Craft home — four features" style="max-width:320px;border-radius:12px;margin:12px 0;"><blockquote><p>Install note: Android blocks &quot;unknown sources&quot; the first time. Go to <code>Settings → Apps → Special app access → Install unknown apps → Allow from this source</code>, then tap the APK again.</p><p>iOS users: there is no available build yet — please bookmark <a href="https://acecrush.dev" target="_blank" rel="noreferrer">acecrush.dev</a> to get notified at launch.</p></blockquote><h3 id="package-information" tabindex="-1">Package information <a class="header-anchor" href="#package-information" aria-label="Permalink to &quot;Package information&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Package name</td><td><code>com.acecrushcraft.app</code></td></tr><tr><td>Minimum Android</td><td>Android 7.0 (API 24)</td></tr><tr><td>Target Android</td><td>Android 14 (API 34)</td></tr><tr><td>APK size</td><td>~50 MB (per-ABI split: ~30 MB per CPU arch)</td></tr><tr><td>Root required</td><td>❌ No</td></tr><tr><td>Google Play Services required</td><td>❌ No</td></tr><tr><td>Data storage</td><td>Device-local SQLite</td></tr></tbody></table><hr><h2 id="🚀-quick-start" tabindex="-1">🚀 Quick start <a class="header-anchor" href="#🚀-quick-start" aria-label="Permalink to &quot;🚀 Quick start&quot;">​</a></h2><p>After installing V1.0, the minimum getting-started path:</p><ol><li>Open <a href="./guide/01-getting-started.html">01 · Getting Started</a> and grant permissions + notification</li><li>Try <a href="./guide/02-grip-size-measurement.html">02 · Grip Size Measurement</a> once with a palm photo (or a ruler)</li><li>Add one main racket in <a href="./guide/03-racquets.html">03 · Rackets</a> and set a renewal reminder via <a href="./guide/04-stringing-log.html">04 · Stringing Log</a></li><li>Convert tension units whenever you need it: <a href="./guide/05-tension-conversion.html">05 · Tension Conversion</a> → tap <strong>&quot;Use this tension → log stringing&quot;</strong> to drop the result straight into a restring record</li></ol><h2 id="📑-documentation-index" tabindex="-1">📑 Documentation index <a class="header-anchor" href="#📑-documentation-index" aria-label="Permalink to &quot;📑 Documentation index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chapter</th><th>Contents</th><th>For whom</th></tr></thead><tbody><tr><td><a href="./guide/00-introduction.html">00 · Introduction</a></td><td>App positioning, the four features, version roadmap, three pillars</td><td>First encounter — start here</td></tr><tr><td><a href="./guide/01-getting-started.html">01 · Getting Started</a></td><td>Install, permissions, home screen, navigation, language + theme</td><td>New users — 5 minutes</td></tr><tr><td><a href="./guide/02-grip-size-measurement.html">02 · Grip Size Measurement</a></td><td>Palm photo → MediaPipe Hand → recommended size (or ruler manual)</td><td>Players who don&#39;t know their grip size</td></tr><tr><td><a href="./guide/03-racquets.html">03 · Rackets (Profile)</a></td><td>Add / edit / delete rackets and their specs</td><td>Owners of ≥ 1 racket</td></tr><tr><td><a href="./guide/04-stringing-log.html">04 · Stringing Log</a></td><td>One record per restring + automatic reminders</td><td>Anyone who restring their rackets</td></tr><tr><td><a href="./guide/05-tension-conversion.html">05 · Tension Conversion</a></td><td>DT ⇄ RT ⇄ lbs ⇄ kg; &quot;Use this tension → log stringing&quot; CTA</td><td>Buyers / adjusters of tension</td></tr><tr><td><a href="./guide/06-cloud-sync.html">06 · Cloud Sync (BYO Supabase)</a></td><td>Multi-device sync + photo cloud backup (BYO model, opt-in)</td><td>Anyone wanting shared data across devices</td></tr><tr><td><a href="./guide/07-settings.html">07 · Settings</a></td><td>Theme / units / font / data / notifications</td><td>When changing look or exporting data</td></tr><tr><td><a href="./guide/08-privacy.html">08 · Privacy</a></td><td>Permission manifest, open-source licenses, third-party components</td><td>When reviewing what&#39;s requested</td></tr><tr><td><a href="./guide/09-feedback.html">09 · Feedback</a></td><td>Feedback template, email, Xiaohongshu</td><td>Bug / suggestion</td></tr><tr><td><a href="./guide/10-faq.html">10 · FAQ</a></td><td>13 FAQs (free / iOS / upload / data recovery, etc.)</td><td>Whenever</td></tr></tbody></table><h2 id="🔒-privacy-promise" tabindex="-1">🔒 Privacy promise <a class="header-anchor" href="#🔒-privacy-promise" aria-label="Permalink to &quot;🔒 Privacy promise&quot;">​</a></h2><ul><li><strong>All personal data stays on-device</strong> (SQLite inside the app sandbox). Uninstall ⇒ wiped</li><li><strong>No upload of your sports data</strong> — stringing logs, grip measurements, and tension-conversion results never leave your phone</li><li><strong>AI grip measurement</strong>: runs MediaPipe entirely on-device; the image never leaves your phone</li><li>Full manifest: <a href="./guide/08-privacy.html">08 · Privacy</a></li></ul><h2 id="📮-feedback" tabindex="-1">📮 Feedback <a class="header-anchor" href="#📮-feedback" aria-label="Permalink to &quot;📮 Feedback&quot;">​</a></h2><ul><li>Email: <a href="mailto:acecrushdev@gmail.com" target="_blank" rel="noreferrer">acecrushdev@gmail.com</a></li><li>Xiaohongshu: <code>@AceCrush</code></li></ul><h2 id="📄-license-acknowledgements" tabindex="-1">📄 License &amp; acknowledgements <a class="header-anchor" href="#📄-license-acknowledgements" aria-label="Permalink to &quot;📄 License &amp; acknowledgements&quot;">​</a></h2><ul><li>The app is <strong>not yet open source</strong> (a decision will be made after the V1.0 store launch)</li><li>Bundled <a href="https://github.com/google-ai-edge/mediapipe" target="_blank" rel="noreferrer">MediaPipe</a> (Pose / Hand models) is licensed under Apache License 2.0; the full license text is available in-app under <code>Me → Open-source licenses</code></li><li>Trademarks: <code>AceCrush</code> and the logo are property of the AceCrush team; use without permission is prohibited</li></ul>',28)])])}const f=a(n,[["render",d]]);export{m as __pageData,f as default};
